 create or replace function public.cb_touch_updated_at() returns trigger language plpgsql security definer set search_path to 'public' as $$ begin new.updated_at = now(); return new; end $$; create table if not exists public.cb_workspaces (   id uuid primary key default gen_random_uuid(),   name text not null,   origin text not null default 'standalone' check (origin in ('platform','standalone')),   gc_company_id uuid references public.companies(id) on delete set null,   measure_credits int not null default 3,   plan text not null default 'free' check (plan in ('free','pro','team')),   created_by uuid references auth.users(id) on delete set null,   created_at timestamptz not null default now(),   updated_at timestamptz not null default now(),   unique (gc_company_id) ); create table if not exists public.cb_workspace_members (   id uuid primary key default gen_random_uuid(),   workspace_id uuid not null references public.cb_workspaces(id) on delete cascade,   user_id uuid not null references auth.users(id) on delete cascade,   role text not null default 'rep' check (role in ('admin','manager','rep')),   created_at timestamptz not null default now(),   unique (workspace_id, user_id) ); create table if not exists public.cb_companies (   id uuid primary key default gen_random_uuid(),   workspace_id uuid not null references public.cb_workspaces(id) on delete cascade,   gc_company_id uuid references public.companies(id) on delete set null,   name text not null,   legal_name text,   logo_url text,   primary_color text not null default '#1F425D',   accent_color text not null default '#E21F2F',   phone text, email text, website text,   address text, city text, state text, zip text,   license_numbers jsonb not null default '[]'::jsonb,   insurance_note text,   warranty_years int,   about_headline text,   about_story text,   service_areas jsonb not null default '[]'::jsonb,   founded_year int,   team_photo_url text,   is_template boolean not null default true,   is_locked boolean not null default false,   created_at timestamptz not null default now(),   updated_at timestamptz not null default now() ); create table if not exists public.cb_jobs (   id uuid primary key default gen_random_uuid(),   workspace_id uuid not null references public.cb_workspaces(id) on delete cascade,   company_id uuid not null references public.cb_companies(id) on delete restrict,   created_by uuid references auth.users(id) on delete set null,   status text not null default 'draft'     check (status in ('draft','inspecting','report_ready','presented','signed','converted')),   customer_name text, customer_phone text, customer_email text,   address text, city text, state text, zip text,   lat numeric, lng numeric,   carrier text, claim_number text,   date_of_loss date, inspection_date date default current_date,   adjuster_name text, adjuster_phone text,   deductible numeric,   cover_photo_path text,   scopes jsonb not null default '[]'::jsonb,   gc_job_id uuid references public.jobs(id) on delete set null,   converted_at timestamptz,   converted_by uuid references auth.users(id) on delete set null,   created_at timestamptz not null default now(),   updated_at timestamptz not null default now() ); create table if not exists public.cb_takeoffs (   id uuid primary key default gen_random_uuid(),   job_id uuid not null unique references public.cb_jobs(id) on delete cascade,   data jsonb not null default '{}'::jsonb,   elevations jsonb not null default '{}'::jsonb,   completeness int not null default 0,   updated_at timestamptz not null default now() ); create table if not exists public.cb_measurements (   id uuid primary key default gen_random_uuid(),   job_id uuid not null unique references public.cb_jobs(id) on delete cascade,   source text not null default 'manual' check (source in ('instant','manual')),   rep_adjusted boolean not null default false,   total_squares numeric not null default 0,   total_area_sqft numeric not null default 0,   waste_pct numeric not null default 10,   pitch text,   stories int,   facets int,   ridge_lf numeric not null default 0,   hip_lf numeric not null default 0,   valley_lf numeric not null default 0,   rake_lf numeric not null default 0,   eave_lf numeric not null default 0,   drip_edge_lf numeric not null default 0,   starter_lf numeric not null default 0,   ridge_cap_lf numeric not null default 0,   wall_flashing_lf numeric not null default 0,   step_flashing_lf numeric not null default 0,   gutter_lf numeric not null default 0,   raw jsonb not null default '{}'::jsonb,   created_at timestamptz not null default now(),   updated_at timestamptz not null default now() ); create table if not exists public.cb_photos (   id uuid primary key default gen_random_uuid(),   job_id uuid not null references public.cb_jobs(id) on delete cascade,   workspace_id uuid not null references public.cb_workspaces(id) on delete cascade,   uploaded_by uuid references auth.users(id) on delete set null,   storage_path text not null,   thumb_path text,   category text not null default 'roof' check (category in ('cover','roof','exterior','interior','other')),   elevation text check (elevation in ('front','right','rear','left','na')),   shot_type text check (shot_type in ('wide','medium','close','test_square')),   item_key text,   caption text,   lat numeric, lng numeric,   taken_at timestamptz,   sort_order int not null default 0,   created_at timestamptz not null default now() ); create table if not exists public.cb_reports (   id uuid primary key default gen_random_uuid(),   job_id uuid not null references public.cb_jobs(id) on delete cascade,   version int not null default 1,   narrative jsonb not null default '{}'::jsonb,   line_items jsonb not null default '[]'::jsonb,   ventilation jsonb not null default '{}'::jsonb,   pdf_path text,   share_token text unique,   share_expires_at timestamptz,   generated_by uuid references auth.users(id) on delete set null,   generated_at timestamptz not null default now(),   unique (job_id, version) ); create table if not exists public.cb_contracts (   id uuid primary key default gen_random_uuid(),   job_id uuid not null references public.cb_jobs(id) on delete cascade,   doc_type text not null default 'contingency' check (doc_type in ('contingency','retail')),   body_html text,   signer_name text, signer_email text,   signature_png text,   signed_at timestamptz,   ip inet, user_agent text,   pdf_path text,   created_at timestamptz not null default now() ); create table if not exists public.cb_audit_log (   id uuid primary key default gen_random_uuid(),   workspace_id uuid references public.cb_workspaces(id) on delete cascade,   actor uuid references auth.users(id) on delete set null,   action text not null,   entity text, entity_id uuid,   meta jsonb not null default '{}'::jsonb,   created_at timestamptz not null default now() ); create index if not exists cb_workspace_members_user_idx on public.cb_workspace_members(user_id); create index if not exists cb_companies_ws_idx on public.cb_companies(workspace_id); create index if not exists cb_jobs_ws_idx on public.cb_jobs(workspace_id); create index if not exists cb_jobs_creator_idx on public.cb_jobs(created_by); create index if not exists cb_jobs_status_idx on public.cb_jobs(workspace_id, status); create index if not exists cb_photos_job_idx on public.cb_photos(job_id); create index if not exists cb_photos_lookup_idx on public.cb_photos(job_id, category, elevation); create index if not exists cb_reports_job_idx on public.cb_reports(job_id); create index if not exists cb_contracts_job_idx on public.cb_contracts(job_id); drop trigger if exists cb_workspaces_touch on public.cb_workspaces; create trigger cb_workspaces_touch before update on public.cb_workspaces   for each row execute function public.cb_touch_updated_at(); drop trigger if exists cb_companies_touch on public.cb_companies; create trigger cb_companies_touch before update on public.cb_companies   for each row execute function public.cb_touch_updated_at(); drop trigger if exists cb_jobs_touch on public.cb_jobs; create trigger cb_jobs_touch before update on public.cb_jobs   for each row execute function public.cb_touch_updated_at(); drop trigger if exists cb_takeoffs_touch on public.cb_takeoffs; create trigger cb_takeoffs_touch before update on public.cb_takeoffs   for each row execute function public.cb_touch_updated_at(); drop trigger if exists cb_measurements_touch on public.cb_measurements; create trigger cb_measurements_touch before update on public.cb_measurements   for each row execute function public.cb_touch_updated_at(); create or replace function public.cb_workspace_ids() returns setof uuid language sql stable security definer set search_path to 'public' as $$   select workspace_id from public.cb_workspace_members where user_id = auth.uid(); $$; create or replace function public.cb_role(_ws uuid) returns text language sql stable security definer set search_path to 'public' as $$   select role from public.cb_workspace_members where workspace_id = _ws and user_id = auth.uid(); $$; create or replace function public.cb_is_admin(_ws uuid) returns boolean language sql stable security definer set search_path to 'public' as $$   select exists (select 1 from public.cb_workspace_members     where workspace_id = _ws and user_id = auth.uid() and role = 'admin'); $$; create or replace function public.cb_sees_all(_ws uuid) returns boolean language sql stable security definer set search_path to 'public' as $$   select exists (select 1 from public.cb_workspace_members     where workspace_id = _ws and user_id = auth.uid() and role in ('admin','manager')); $$; create or replace function public.cb_has_gc_access() returns boolean language sql stable security definer set search_path to 'public' as $$   select exists (select 1 from public.profiles where id = auth.uid() and company_id is not null); $$; create or replace function public.cb_gc_company_id() returns uuid language sql stable security definer set search_path to 'public' as $$   select company_id from public.profiles where id = auth.uid(); $$; create or replace function public.cb_can_access_job(_job uuid) returns boolean language sql stable security definer set search_path to 'public' as $$   select exists (     select 1 from public.cb_jobs j     join public.cb_workspace_members m       on m.workspace_id = j.workspace_id and m.user_id = auth.uid()     where j.id = _job       and (m.role in ('admin','manager') or j.created_by = auth.uid())   ); $$; alter table public.cb_workspaces        enable row level security; alter table public.cb_workspace_members enable row level security; alter table public.cb_companies         enable row level security; alter table public.cb_jobs              enable row level security; alter table public.cb_takeoffs          enable row level security; alter table public.cb_measurements      enable row level security; alter table public.cb_photos            enable row level security; alter table public.cb_reports           enable row level security; alter table public.cb_contracts         enable row level security; alter table public.cb_audit_log         enable row level security; create policy cb_ws_select on public.cb_workspaces for select to authenticated   using (id in (select public.cb_workspace_ids())); create policy cb_ws_update on public.cb_workspaces for update to authenticated   using (public.cb_is_admin(id)) with check (public.cb_is_admin(id)); create policy cb_ws_delete on public.cb_workspaces for delete to authenticated   using (public.cb_is_admin(id)); create policy cb_wsm_select on public.cb_workspace_members for select to authenticated   using (workspace_id in (select public.cb_workspace_ids())); create policy cb_wsm_insert on public.cb_workspace_members for insert to authenticated   with check (public.cb_is_admin(workspace_id)); create policy cb_wsm_update on public.cb_workspace_members for update to authenticated   using (public.cb_is_admin(workspace_id)) with check (public.cb_is_admin(workspace_id)); create policy cb_wsm_delete on public.cb_workspace_members for delete to authenticated   using (public.cb_is_admin(workspace_id)); create policy cb_co_select on public.cb_companies for select to authenticated   using (workspace_id in (select public.cb_workspace_ids())); create policy cb_co_insert on public.cb_companies for insert to authenticated   with check (public.cb_is_admin(workspace_id)); create policy cb_co_update on public.cb_companies for update to authenticated   using (public.cb_is_admin(workspace_id)) with check (public.cb_is_admin(workspace_id)); create policy cb_co_delete on public.cb_companies for delete to authenticated   using (public.cb_is_admin(workspace_id)); create policy cb_job_select on public.cb_jobs for select to authenticated   using (workspace_id in (select public.cb_workspace_ids())          and (public.cb_sees_all(workspace_id) or created_by = auth.uid())); create policy cb_job_insert on public.cb_jobs for insert to authenticated   with check (workspace_id in (select public.cb_workspace_ids()) and created_by = auth.uid()); create policy cb_job_update on public.cb_jobs for update to authenticated   using (workspace_id in (select public.cb_workspace_ids())          and (public.cb_sees_all(workspace_id) or created_by = auth.uid()))   with check (workspace_id in (select public.cb_workspace_ids())); create policy cb_job_delete on public.cb_jobs for delete to authenticated   using (workspace_id in (select public.cb_workspace_ids())          and (public.cb_is_admin(workspace_id) or created_by = auth.uid())); create policy cb_to_all on public.cb_takeoffs for all to authenticated   using (public.cb_can_access_job(job_id)) with check (public.cb_can_access_job(job_id)); create policy cb_ms_all on public.cb_measurements for all to authenticated   using (public.cb_can_access_job(job_id)) with check (public.cb_can_access_job(job_id)); create policy cb_ph_all on public.cb_photos for all to authenticated   using (public.cb_can_access_job(job_id)) with check (public.cb_can_access_job(job_id)); create policy cb_rp_all on public.cb_reports for all to authenticated   using (public.cb_can_access_job(job_id)) with check (public.cb_can_access_job(job_id)); create policy cb_ct_all on public.cb_contracts for all to authenticated   using (public.cb_can_access_job(job_id)) with check (public.cb_can_access_job(job_id)); create policy cb_audit_select on public.cb_audit_log for select to authenticated   using (workspace_id in (select public.cb_workspace_ids())); create policy cb_audit_insert on public.cb_audit_log for insert to authenticated   with check (workspace_id in (select public.cb_workspace_ids()) and actor = auth.uid()); create or replace function public.cb_bootstrap_workspace(_workspace_name text, _company jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path to 'public' as $$ declare _ws uuid; _co uuid; _uid uuid := auth.uid(); begin   if _uid is null then raise exception 'not authenticated'; end if;   insert into public.cb_workspaces (name, origin, created_by)   values (coalesce(nullif(_workspace_name,''),'My Company'), 'standalone', _uid) returning id into _ws;   insert into public.cb_workspace_members (workspace_id, user_id, role) values (_ws, _uid, 'admin');   insert into public.cb_companies (workspace_id, name, legal_name, logo_url, primary_color, accent_color,     phone, email, website, address, city, state, zip, license_numbers)   values (_ws, coalesce(_company->>'name', _workspace_name, 'My Company'), _company->>'legal_name',     _company->>'logo_url', coalesce(_company->>'primary_color','#1F425D'),     coalesce(_company->>'accent_color','#E21F2F'), _company->>'phone', _company->>'email',     _company->>'website', _company->>'address', _company->>'city', _company->>'state', _company->>'zip',     coalesce(_company->'license_numbers','[]'::jsonb)) returning id into _co;   insert into public.cb_audit_log (workspace_id, actor, action, entity, entity_id)   values (_ws, _uid, 'workspace.created.standalone', 'cb_workspaces', _ws);   return jsonb_build_object('workspace_id', _ws, 'company_id', _co, 'origin','standalone'); end $$; create or replace function public.cb_ensure_platform_workspace() returns jsonb language plpgsql security definer set search_path to 'public' as $$ declare _uid uuid := auth.uid(); _gc uuid; _ws uuid; _co uuid; _gcname text; _role text; _prole text; begin   if _uid is null then raise exception 'not authenticated'; end if;   select company_id, role::text into _gc, _prole from public.profiles where id = _uid;   if _gc is null then raise exception 'no GlobalContractor company on this account'; end if;   _role := case when _prole in ('owner','admin','super_admin') then 'admin'                 when _prole = 'estimator' then 'manager' else 'rep' end;   select id into _ws from public.cb_workspaces where gc_company_id = _gc;   if _ws is null then     select name into _gcname from public.companies where id = _gc;     insert into public.cb_workspaces (name, origin, gc_company_id, created_by, measure_credits, plan)     values (coalesce(_gcname,'Company'), 'platform', _gc, _uid, 999999, 'team') returning id into _ws;   end if;   insert into public.cb_workspace_members (workspace_id, user_id, role) values (_ws, _uid, _role)   on conflict (workspace_id, user_id) do update set role = excluded.role;   select id into _co from public.cb_companies where workspace_id = _ws and gc_company_id = _gc;   if _co is null then     insert into public.cb_companies (workspace_id, gc_company_id, name, is_locked)     values (_ws, _gc, coalesce((select name from public.companies where id=_gc),'Company'), true)     returning id into _co;   end if;   update public.cb_companies c set     name = g.name, logo_url = coalesce(g.logo_url, c.logo_url), phone = coalesce(g.phone, c.phone),     email = coalesce(g.email, c.email), website = coalesce(g.website, c.website),     address = coalesce(g.address, c.address), license_numbers = to_jsonb(g.license_numbers),     insurance_note = coalesce(g.warranty_blurb, c.insurance_note), is_locked = true, updated_at = now()   from public.companies g where c.id = _co and g.id = _gc;   return jsonb_build_object('workspace_id', _ws, 'company_id', _co, 'origin','platform',                             'gc_company_id', _gc, 'role', _role); end $$; create or replace function public.cb_my_context() returns jsonb language sql stable security definer set search_path to 'public' as $$   select jsonb_build_object(     'user_id', auth.uid(),     'has_gc_access', public.cb_has_gc_access(),     'gc_company_id', public.cb_gc_company_id(),     'workspaces', coalesce((       select jsonb_agg(jsonb_build_object('id', w.id, 'name', w.name, 'origin', w.origin,         'gc_company_id', w.gc_company_id, 'plan', w.plan,         'measure_credits', w.measure_credits, 'role', m.role))       from public.cb_workspaces w       join public.cb_workspace_members m on m.workspace_id = w.id       where m.user_id = auth.uid()), '[]'::jsonb)); $$; create or replace function public.cb_can_convert(_job uuid) returns jsonb language plpgsql stable security definer set search_path to 'public' as $$ declare _gc uuid; _ok boolean; _existing uuid; _gcname text; begin   _ok := public.cb_can_access_job(_job);   _gc := public.cb_gc_company_id();   select gc_job_id into _existing from public.cb_jobs where id = _job;   select name into _gcname from public.companies where id = _gc;   return jsonb_build_object(     'can_convert', (_ok and _gc is not null and _existing is null),     'reason', case when not _ok then 'no_access_to_job'                    when _gc is null then 'no_globalcontractor_account'                    when _existing is not null then 'already_converted' else null end,     'gc_company_id', _gc, 'gc_company_name', _gcname, 'gc_job_id', _existing); end $$; create or replace function public.cb_convert_to_job(_job uuid) returns jsonb language plpgsql security definer set search_path to 'public' as $$ declare   _uid uuid := auth.uid(); _gc uuid; j public.cb_jobs%rowtype;   _client uuid; _prop uuid; _newjob uuid; _rm uuid;   _m public.cb_measurements%rowtype; _photos int := 0; _label text; begin   if _uid is null then raise exception 'not authenticated'; end if;   if not public.cb_can_access_job(_job) then raise exception 'You do not have access to this inspection'; end if;   _gc := public.cb_gc_company_id();   if _gc is null then     raise exception 'This account has Claim Buddy only. A GlobalContractor seat is required to create a job.';   end if;   select * into j from public.cb_jobs where id = _job;   if j.gc_job_id is not null then     return jsonb_build_object('gc_job_id', j.gc_job_id, 'already', true);   end if;   _label := coalesce(nullif(j.customer_name,''), nullif(j.address,''), 'Claim Buddy inspection');   select id into _client from public.clients where company_id = _gc and lower(name) = lower(_label) limit 1;   if _client is null then     insert into public.clients (company_id, name, email, phone, address)     values (_gc, _label, j.customer_email, j.customer_phone, j.address) returning id into _client;   end if;   insert into public.properties (company_id, client_id, address, city, state, zip, lat, lng, property_type)   values (_gc, _client, coalesce(j.address,'Unknown'), j.city, j.state, j.zip, j.lat, j.lng, 'residential')   returning id into _prop;   insert into public.jobs (company_id, client_id, property_id, name, property_address, status,     primary_trade, job_type, claim_number, insurance_carrier, created_by, assigned_to, roof_system, notes)   values (_gc, _client, _prop, _label || ' - ' || coalesce(j.address,''), j.address,     'inspected'::job_status, 'roofing'::trade_type, 'insurance', j.claim_number, j.carrier, _uid, _uid,     (select data->'roof'->>'roof_type' from public.cb_takeoffs where job_id = _job),     'Imported from Claim Buddy inspection ' || _job::text ||       case when j.date_of_loss is not null then ' | Date of loss: ' || j.date_of_loss::text else '' end)   returning id into _newjob;   select * into _m from public.cb_measurements where job_id = _job;   if found then     insert into public.roof_measurements (property_id, company_id, source, predominant_pitch, waste_pct,       squares, total_area_sqft, eaves_lf, rakes_lf, ridges_lf, hips_lf, valleys_lf, gutters_lf,       wall_flashing_lf, step_flashing_lf, created_by, ai_analysis, notes)     values (_prop, _gc,       case when _m.source = 'instant' then 'google_solar'::roof_measurement_source            else 'manual'::roof_measurement_source end,       _m.pitch, _m.waste_pct, _m.total_squares, _m.total_area_sqft, _m.eave_lf, _m.rake_lf, _m.ridge_lf,       _m.hip_lf, _m.valley_lf, _m.gutter_lf, _m.wall_flashing_lf, _m.step_flashing_lf, _uid, _m.raw,       'Imported from Claim Buddy') returning id into _rm;   end if;   insert into public.job_photos (job_id, company_id, uploaded_by, storage_path, caption, tag, taken_at, exif_gps, status)   select _newjob, _gc, _uid, p.storage_path,     coalesce(p.caption, btrim(initcap(coalesce(p.elevation,'')) || ' ' || coalesce(p.shot_type,''))),     coalesce(p.item_key, p.category), p.taken_at,     case when p.lat is not null then jsonb_build_object('lat',p.lat,'lng',p.lng) else null end, 'pending'   from public.cb_photos p where p.job_id = _job;   get diagnostics _photos = row_count;   insert into public.job_documents (job_id, company_id, kind, title, bucket, storage_path, mime_type, source_table, source_id, created_by)   select _newjob, _gc, 'measurement_report', 'Claim Buddy damage report v' || r.version::text,     'cb-documents', r.pdf_path, 'application/pdf', 'cb_reports', r.id, _uid   from public.cb_reports r where r.job_id = _job and r.pdf_path is not null   order by r.version desc limit 1;   insert into public.job_documents (job_id, company_id, kind, title, bucket, storage_path, mime_type, source_table, source_id, created_by)   select _newjob, _gc, case when c.doc_type = 'contingency' then 'contingency' else 'contract' end,     case when c.doc_type = 'contingency' then 'Signed contingency agreement' else 'Signed contract' end,     'cb-documents', c.pdf_path, 'application/pdf', 'cb_contracts', c.id, _uid   from public.cb_contracts c where c.job_id = _job and c.pdf_path is not null and c.signed_at is not null   order by c.signed_at desc limit 1;   update public.cb_jobs set gc_job_id = _newjob, converted_at = now(), converted_by = _uid, status = 'converted'    where id = _job;   insert into public.cb_audit_log (workspace_id, actor, action, entity, entity_id, meta)   values (j.workspace_id, _uid, 'job.converted', 'cb_jobs', _job,     jsonb_build_object('gc_job_id', _newjob, 'gc_company_id', _gc, 'photos', _photos));   return jsonb_build_object('gc_job_id', _newjob, 'gc_client_id', _client, 'gc_property_id', _prop,     'roof_measurement_id', _rm, 'photos_linked', _photos, 'already', false); end $$; create policy cb_storage_read on storage.objects for select to authenticated   using (bucket_id in ('cb-photos','cb-documents')          and ((storage.foldername(name))[1])::uuid in (select public.cb_workspace_ids())); create policy cb_storage_write on storage.objects for insert to authenticated   with check (bucket_id in ('cb-photos','cb-documents')               and ((storage.foldername(name))[1])::uuid in (select public.cb_workspace_ids())); create policy cb_storage_update on storage.objects for update to authenticated   using (bucket_id in ('cb-photos','cb-documents')          and ((storage.foldername(name))[1])::uuid in (select public.cb_workspace_ids())); create policy cb_storage_delete on storage.objects for delete to authenticated   using (bucket_id in ('cb-photos','cb-documents')          and ((storage.foldername(name))[1])::uuid in (select public.cb_workspace_ids())); create policy cb_logo_read on storage.objects for select to public using (bucket_id = 'cb-logos'); create policy cb_logo_write on storage.objects for insert to authenticated   with check (bucket_id = 'cb-logos'               and ((storage.foldername(name))[1])::uuid in (select public.cb_workspace_ids())); create policy cb_logo_update on storage.objects for update to authenticated   using (bucket_id = 'cb-logos'          and ((storage.foldername(name))[1])::uuid in (select public.cb_workspace_ids())); create or replace function public.cb_consume_measure_credit(_ws uuid) returns jsonb language plpgsql security definer set search_path to 'public' as $$ declare _left int; _origin text; begin   if _ws not in (select public.cb_workspace_ids()) then raise exception 'not a member of this workspace'; end if;   select origin into _origin from public.cb_workspaces where id = _ws;   if _origin = 'platform' then     return jsonb_build_object('allowed', true, 'metered', false, 'remaining', null);   end if;   update public.cb_workspaces set measure_credits = measure_credits - 1    where id = _ws and measure_credits > 0 returning measure_credits into _left;   if _left is null then return jsonb_build_object('allowed', false, 'metered', true, 'remaining', 0); end if;   return jsonb_build_object('allowed', true, 'metered', true, 'remaining', _left); end $$; create or replace function public.cb_create_share_link(_report uuid, _days int default 30) returns text language plpgsql security definer set search_path to 'public' as $$ declare _tok text; _job uuid; begin   select job_id into _job from public.cb_reports where id = _report;   if _job is null or not public.cb_can_access_job(_job) then raise exception 'no access to this report'; end if;   _tok := encode(gen_random_bytes(24),'hex');   update public.cb_reports set share_token = _tok, share_expires_at = now() + (_days || ' days')::interval    where id = _report;   return _tok; end $$; create or replace function public.cb_report_by_token(_token text) returns jsonb language sql stable security definer set search_path to 'public' as $$   select jsonb_build_object(     'report', to_jsonb(r) - 'share_token', 'job', to_jsonb(j) - 'created_by',     'company', to_jsonb(c), 'measurements', to_jsonb(m), 'takeoff', to_jsonb(t),     'photos', coalesce((select jsonb_agg(to_jsonb(p) order by p.sort_order)                         from public.cb_photos p where p.job_id = j.id), '[]'::jsonb))   from public.cb_reports r   join public.cb_jobs j on j.id = r.job_id   join public.cb_companies c on c.id = j.company_id   left join public.cb_measurements m on m.job_id = j.id   left join public.cb_takeoffs t on t.job_id = j.id   where r.share_token = _token and r.share_expires_at > now(); $$; create table if not exists public.cb_item_catalog (   id uuid primary key default gen_random_uuid(),   scope text not null check (scope in ('roof','exterior','interior')),   group_name text not null,   item_key text not null unique,   label text not null,   unit text not null default 'ea',   requires_qty boolean not null default true,   sort_order int not null default 0,   active boolean not null default true ); alter table public.cb_item_catalog enable row level security; create policy cb_cat_read on public.cb_item_catalog for select to authenticated using (true); insert into public.cb_item_catalog (scope, group_name, item_key, label, unit, sort_order) values ('exterior','Siding & cladding','ext_siding_vinyl','Siding - vinyl / aluminum','SQ',10), ('exterior','Siding & cladding','ext_siding_wood','Siding - wood / cedar','SQ',11), ('exterior','Siding & cladding','ext_siding_hardie','Siding - Hardie / LP','SQ',12), ('exterior','Siding & cladding','ext_brick_stone','Brick & stone veneer','SF',13), ('exterior','Siding & cladding','ext_stucco','Stucco / Dryvit','SF',14), ('exterior','Siding & cladding','ext_shutters','Shutters','ea',15), ('exterior','Siding & cladding','ext_corner_post','Corner posts / J-channel','LF',16), ('exterior','Siding & cladding','ext_fascia','Fascia','LF',17), ('exterior','Siding & cladding','ext_soffit','Soffit & vents','LF',18), ('exterior','Siding & cladding','ext_frieze','Frieze board